/* LA Lakers DNA — forum purple night, showtime gold lights */
.theme-la-lakers {
  --bg: oklch(0.224 0.075 301.3);
  --surface: oklch(0.259 0.091 300.9);
  --surface-2: oklch(0.303 0.110 300.0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.743 0.059 303.2);
  --accent: oklch(0.828 0.163 80.2);
  --accent-fg: oklch(0.245 0.085 304.9);
  --accent-2: oklch(0.430 0.180 303.0); /* true Lakers purple #552583 */
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-la-lakers h1,
.theme-la-lakers h2,
.theme-la-lakers h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-la-lakers { --font-ui: var(--font-display); }
.theme-la-lakers h1, .theme-la-lakers h2 { text-transform: uppercase; font-weight: 800; }
.theme-la-lakers button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-la-lakers { background-image: radial-gradient(ellipse at 50% -10%, oklch(0.6 0.15 90 / 18%), transparent 50%); }
.theme-la-lakers h1 { background: linear-gradient(95deg, #fdb927, #e2a51f); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* depth */
.theme-la-lakers ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-la-lakers a { color: var(--accent); text-decoration-color: color-mix(in oklab, var(--accent) 55%, transparent); text-underline-offset: 3px; }
.theme-la-lakers a:hover { color: #ffffff; text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
.theme-la-lakers thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--accent); background: oklch(0.195 0.070 301); border-bottom: 2px solid var(--accent); }
.theme-la-lakers td { border-bottom: 1px solid var(--line); }
.theme-la-lakers tbody tr:hover { background: oklch(0.828 0.163 80.2 / 8%); }
.theme-la-lakers input, .theme-la-lakers select, .theme-la-lakers textarea { background: oklch(0.19 0.068 301); border: 1px solid var(--line); caret-color: var(--accent); }
.theme-la-lakers input:focus-visible, .theme-la-lakers select:focus-visible, .theme-la-lakers textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px oklch(0.828 0.163 80.2 / 25%), 0 0 16px oklch(0.828 0.163 80.2 / 20%); }
/* championship-ring plate */
.theme-la-lakers kbd { font-family: var(--font-display); font-weight: 700; background: linear-gradient(180deg, oklch(0.86 0.16 84), oklch(0.76 0.15 76)); color: oklch(0.245 0.085 304.9); border: 1px solid oklch(0.66 0.13 76); border-radius: var(--radius-sm); padding: 0.1em 0.5em; }
.theme-la-lakers ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-la-lakers ::-webkit-scrollbar-track { background: oklch(0.19 0.068 301); }
.theme-la-lakers ::-webkit-scrollbar-thumb { background: oklch(0.66 0.13 80); border: 2px solid oklch(0.19 0.068 301); border-radius: 999px; }
.theme-la-lakers ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-la-lakers .label-caps { color: var(--accent); font-weight: 700; }
.theme-la-lakers .themed-border { border-color: color-mix(in oklab, var(--accent) 55%, transparent); }
/* physical: showtime spotlight — hover pulls the arena lights onto the button */
.theme-la-lakers button:hover { box-shadow: 0 0 20px oklch(0.828 0.163 80.2 / 40%), var(--shadow-1); }
.theme-la-lakers button:active { transform: translateY(1px); box-shadow: 0 0 8px oklch(0.828 0.163 80.2 / 30%); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-la-lakers.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.384 0.150 303.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.828 0.163 80.2);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-la-lakers.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #552583; -webkit-text-stroke: 0; }
.theme-la-lakers.alt-mode thead th { color: oklch(0.828 0.163 80.2); background: oklch(0.34 0.14 303); border-bottom-color: oklch(0.828 0.163 80.2); }
.theme-la-lakers.alt-mode input, .theme-la-lakers.alt-mode select, .theme-la-lakers.alt-mode textarea { background: oklch(1 0 0); border-color: var(--line); }
.theme-la-lakers.alt-mode ::-webkit-scrollbar-track { background: oklch(0.95 0.005 286); }
.theme-la-lakers.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.62 0.12 303); border-color: oklch(0.95 0.005 286); }
.theme-la-lakers.alt-mode tbody tr:hover { background: oklch(0.384 0.150 303.3 / 7%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
